'use strict';
// SSEC RealEarth documented HTTP API. Images, logos and watermarks are retained.
(function(root){
const BASE='https://realearth.ssec.wisc.edu/api/';
const PRODUCTS={globalir:{name:'赤外線',description:'白い部分ほど低温です。雲の上面のほか、冷たい地表も白く見えます。'},globalvis:{name:'可視光',description:'太陽光を反射する雲を観測します。夜側は暗くなり、雲がなくなったわけではありません。'}};
function parseTime(value){const m=/^(\d{4})(\d{2})(\d{2})[._](\d{2})(\d{2})(\d{2})$/.exec(value);if(!m)return null;const iso=`${m[1]}-${m[2]}-${m[3]}T${m[4]}:${m[5]}:${m[6]}Z`;const date=new Date(iso);return Number.isFinite(date.getTime())&&date.toISOString().slice(0,19)===iso.slice(0,19)?date:null;}
function productInfo(data,id){if(!Array.isArray(data))throw Error('観測情報の形式を確認できません');const product=data.find(x=>x.id===id);const times=[...new Set((product?.times||[]).filter(t=>typeof t==='string'&&parseTime(t)))].sort();if(!times.length)throw Error('利用可能な観測時刻がありません');return times;}
function imageURL(product,time,size=1024){if(!PRODUCTS[product]||!parseTime(time))throw Error('Invalid observation');const params=new URLSearchParams({products:product+'_'+time.replace('.','_'),bounds:'-85.05112878,-180,85.05112878,180',width:String(size),height:String(size),format:'png'});return BASE+'image?'+params;}
function bundledSnapshot(){try{return root.GeoData?root.GeoData.snapshot():Promise.resolve(root.GEO_WEATHER_SNAPSHOT||null);}catch(error){return Promise.resolve(null);}}
function mercatorY(latitude){return .5-Math.log(Math.tan(Math.PI/4+latitude*Math.PI/360))/(2*Math.PI);}
class WeatherController{
 constructor({onImage,onEnabled}){this.onImage=onImage;this.onEnabled=onEnabled;this.cache=new Map();this.times={};this.generation=0;this.abort=null;this.current=null;this.lastCheck=0;this.busy=false;this.ui={};for(const id of ['weatherProduct','weatherStatus','weatherDescription','observationTime','weatherTime','refreshWeather','autoWeather','surfaceLabel','flatWeather'])this.ui[id]=document.getElementById(id);}
 imageAddress(product,time,size){return imageURL(product,time,size);}
 async init(skipInitialRefresh=false){const u=this.ui;u.weatherProduct.addEventListener('change',()=>this.changeProduct());u.refreshWeather.addEventListener('click',()=>this.refresh());u.weatherTime.addEventListener('change',()=>{const product=u.weatherProduct.value;const time=this.times[product]?.[Number(u.weatherTime.value)];if(time)this.show(product,time);});
 this.timer=setInterval(()=>{if(u.autoWeather.checked&&!document.hidden&&u.weatherProduct.value!=='earth'&&!this.busy)this.refresh();},60*60*1000);
 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&u.autoWeather.checked&&Date.now()-this.lastCheck>60*60*1000&&!this.busy&&u.weatherProduct.value!=='earth')this.refresh();});
 const snapshot=await bundledSnapshot();const id=u.weatherProduct.value;if(snapshot?.[id]){const s=snapshot[id];this.times[id]=[s.time];await this.show(id,s.time,s.url,true);}if(!skipInitialRefresh&&u.weatherProduct.value===id)await this.refresh();}
 token(){this.abort?.abort();this.abort=new AbortController();return {generation:++this.generation,signal:this.abort.signal};}
 valid(token){return token.generation===this.generation&&!token.signal.aborted;}
 loading(message){this.busy=true;this.ui.refreshWeather.disabled=true;this.ui.weatherTime.disabled=true;this.ui.weatherStatus.textContent=message;}
 done(){this.busy=false;this.ui.refreshWeather.disabled=this.ui.weatherProduct.value==='earth';this.ui.weatherTime.disabled=this.current?.product!==this.ui.weatherProduct.value||(this.times[this.ui.weatherProduct.value]?.length||0)<2||this.ui.weatherProduct.value==='earth';}
 async request(url,signal){const controller=new AbortController();const abort=()=>controller.abort();signal.addEventListener('abort',abort,{once:true});const timeout=setTimeout(abort,30000);try{if(signal.aborted)controller.abort();const response=await fetch(url,{signal:controller.signal,mode:'cors',credentials:'omit'});if(!response.ok)throw Error('HTTP '+response.status);return await response.blob();}finally{clearTimeout(timeout);signal.removeEventListener('abort',abort);}}
 async loadImage(url,signal){const blob=await this.request(url,signal);if(!blob.type.startsWith('image/'))throw Error('観測画像の形式が不正です');const objectURL=URL.createObjectURL(blob);try{return await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('観測画像を読み込めません'));image.src=objectURL;});}finally{URL.revokeObjectURL(objectURL);}}
 async refresh(){const product=this.ui.weatherProduct.value;if(!PRODUCTS[product])return;const token=this.token();this.loading('最新の観測時刻を確認しています…');this.lastCheck=Date.now();try{const blob=await this.request(BASE+'products?'+new URLSearchParams({products:product,timespan:'-24h'}),token.signal);const times=productInfo(JSON.parse(await blob.text()),product);if(!this.valid(token))return;this.times[product]=times;await this.loadAndApply(product,times.at(-1),token);}catch(error){if(this.valid(token))this.reportError();}finally{if(this.valid(token))this.done();}}
 async show(product,time,url,saved=false){const token=this.token();this.loading('選択した観測画像を読み込んでいます…');try{await this.loadAndApply(product,time,token,url,saved);}catch(error){if(this.valid(token))this.reportError();}finally{if(this.valid(token))this.done();}}
 async loadAndApply(product,time,token,url,saved=false){const key=product+':'+time;let entry=this.cache.get(key);if(!entry){const source=url||imageURL(product,time);const image=await this.loadImage(source,token.signal);entry={image,source,saved};if(!this.valid(token))return;this.cache.set(key,entry);if(this.cache.size>26)this.cache.delete(this.cache.keys().next().value);}if(!this.valid(token))return;this.onImage(entry.image,time);this.onEnabled(true);this.current={product,time,saved:entry.saved};this.renderCurrent();}
 renderCurrent(){const u=this.ui,c=this.current;if(!c)return;const date=parseTime(c.time);u.observationTime.dateTime=date.toISOString();u.observationTime.textContent=new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(date)+' 日本時間';u.surfaceLabel.textContent=PRODUCTS[c.product].name+(document.getElementById('rawObservation')?.checked?'の観測画像':'の観測から合成した雲');u.weatherDescription.textContent=PRODUCTS[c.product].description;const age=Date.now()-date.getTime();const latest=this.times[c.product]?.at(-1);u.weatherStatus.textContent=(c.time!==latest?'過去の観測を表示中':age>6*60*60*1000?'観測から6時間以上経過しています':c.saved?'同梱の観測画像を表示中':'取得した観測画像を表示中');const times=this.times[c.product]||[c.time];u.weatherTime.max=String(times.length-1);u.weatherTime.value=String(Math.max(0,times.indexOf(c.time)));u.flatWeather.href=imageURL(c.product,c.time);u.flatWeather.hidden=false;}
 reportError(){if(this.current){this.onEnabled(true);this.renderCurrent();}this.ui.weatherStatus.textContent=this.current?'取得できませんでした。表示中の日時の観測画像を保持しています。':'観測画像を取得できません。地球の参考画像を表示しています。接続後に「最新を取得」を押してください。';if(!this.current){this.onEnabled(false);this.ui.surfaceLabel.textContent='参考画像・現在の観測ではありません';this.ui.observationTime.textContent='観測画像は未取得';}}
 async changeProduct(){const product=this.ui.weatherProduct.value;this.token();if(product==='earth'){this.onEnabled(false);this.ui.surfaceLabel.textContent='参考画像・現在の観測ではありません';this.ui.weatherDescription.textContent='雲のない地表の参考画像です。現在の観測は表示していません。';this.ui.weatherStatus.textContent='気象データの表示はオフ';this.ui.observationTime.textContent='観測日時なし';this.ui.observationTime.removeAttribute('datetime');this.ui.flatWeather.hidden=true;this.done();return;}this.ui.weatherDescription.textContent=PRODUCTS[product].description;const snapshot=(await bundledSnapshot())?.[product];if(snapshot&&!this.times[product]){this.times[product]=[snapshot.time];await this.show(product,snapshot.time,snapshot.url,true);}if(this.ui.weatherProduct.value===product)await this.refresh();}
}
root.WeatherController=WeatherController;
if(typeof module!=='undefined')module.exports={parseTime,productInfo,imageURL,mercatorY,WeatherController};
})(typeof window==='undefined'?globalThis:window);
